/* eslint-disable @typescript-eslint/indent */
import Path from 'node:path';
import fs from 'node:fs';
import * as rx from 'rxjs';
import {getLogger} from 'log4js';
import fsext from 'fs-extra';
import {ReactorComposite2, SingleActionFactory, ActionTableDataType} from '../../../packages/reactivizer';
import {plinkEnv} from '../utils/misc';
import {PackageJsonInterf} from './package-mgr2-utils';
import {NpmOptions, PackageInfo, createPackageInfo, WorkspaceState,
  pathToProjKey} from './index';

const {rootDir, symlinkDirName} = plinkEnv;
const log = getLogger('plink.package-mgr2');

type PackagesInput = {
  /** load project state from file */
  loadCache(): SingleActionFactory;
  /** scan current project */
  scan(): SingleActionFactory;
  /** Create symlinks and install dependency */
  syncWorkspace(workspace: string): SingleActionFactory;
};

interface PackagesChangeTable {
  npmInstallOpt(data: NpmOptions): SingleActionFactory;
  inited(d: boolean): SingleActionFactory;
  srcPackages(d: Map<string, PackageInfo>): SingleActionFactory;
  /** Key is relative path to root workspace */
  workspaces(d: Map<string, WorkspaceState>): SingleActionFactory;
  /** key of current "workspaces" */
  currWorkspace(d?: string | null): SingleActionFactory;
  project2Packages(data: Map<string, string[]>): SingleActionFactory;
  srcDir2Packages(data: Map<string, string[]>): SingleActionFactory;
  /** Drcp is the original name of Plink project */
  linkedDrcp(data?: PackageInfo | null): SingleActionFactory;
  linkedDrcpProject(data?: string | null): SingleActionFactory;
  installedDrcp(data?: PackageInfo | null): SingleActionFactory;
  gitIgnores(data: {[file: string]: string[]}): SingleActionFactory;
  isInChina(data?: boolean): SingleActionFactory;
  /** Everytime a hoist workspace state calculation is basically done, it is increased by 1 */
  workspaceUpdateChecksum(data: number): SingleActionFactory;
  packagesUpdateChecksum(data: number): SingleActionFactory;
  /** workspace key */
  lastCreatedWorkspace(data?: string): SingleActionFactory;
}

interface PackagesChanges {
  onProjectLinked(projDir: string): SingleActionFactory;
  onProjectUnlinked(projDir: string): SingleActionFactory;
  onDirLinked(dir: string): SingleActionFactory;
  onDirUnlinked(dir: string): SingleActionFactory;
  onPackageRemoved(projOrDirKey: string, pkg: PackageInfo): SingleActionFactory;
  /** package.json is changed */
  onPackageUpdated(projOrDirKey: string, pkg: PackageInfo): SingleActionFactory;
  onSpaceRemoved(wsKey: string): SingleActionFactory;
  /** "dependencies, devDependencies" property of package.json were changed */
  onSpaceUpdated(wsKey: string): SingleActionFactory;
}

const packageChangesTable = ['onPackageUpdated', 'onPackageUpdated', 'onSpaceRemoved', 'onSpaceUpdated'] as const;

interface PackagesEvents extends PackagesChangeTable {
  onScanned(changes: ActionTableDataType<PackagesChanges, typeof packageChangesTable>): SingleActionFactory;
  currentSpace(wsKey: string): SingleActionFactory;
}

const outputTableFor = [
  'currentSpace',
  'inited', 'workspaces', 'project2Packages', 'srcDir2Packages', 'srcPackages',
  'gitIgnores', 'workspaceUpdateChecksum', 'packagesUpdateChecksum', 'npmInstallOpt', 'currWorkspace',
  'linkedDrcp', 'linkedDrcpProject', 'installedDrcp', 'isInChina'
] as const;

export const packagesService = new ReactorComposite2<PackagesInput, PackagesEvents, [], typeof outputTableFor>({
  name: 'PackageMgr2',
  outputTableFor,
  log(msg, ...obj) {
    log.info(msg, ...obj);
  }
});

const {i, o, r, outputTable} = packagesService;

r('scan -> onScanned, project2Packages, srcDir2Packages, inited, srcPackages', i.pt.scan.pipe(
  rx.withLatestFrom(
    outputTable.l.project2Packages,
    outputTable.l.srcDir2Packages
  ),
  rx.concatMap(async ([[m], [, project2Packages], [, srcDir2Packages]]) => {
    const projPkgMap: Map<string, PackageInfo[]> = new Map();
    const srcPkgMap: Map<string, PackageInfo[]> = new Map();
    const rm = (await import('../recipe-manager.js'));
    const pkgList = [] as PackageInfo[];
    await rx.lastValueFrom(rm.scanPackages().pipe(
      rx.tap(([proj, jsonFile, srcDir]) => {
        if (proj && !projPkgMap.has(proj))
          projPkgMap.set(proj, []);
        if (proj == null && srcDir && !srcPkgMap.has(srcDir))
          srcPkgMap.set(srcDir, []);

        log.debug('scan package.json', jsonFile);
        const info = createPackageInfo(jsonFile, false);
        if (info.json.dr || info.json.plink) {
          pkgList.push(info);
          if (proj)
            projPkgMap.get(proj)!.push(info);
          else if (srcDir)
            srcPkgMap.get(srcDir)!.push(info);
          else
            log.error(`Orphan ${jsonFile}`);
        } else {
          log.debug(`Package of ${jsonFile} is skipped (due to no "dr" or "plink" property)`, info.json);
        }
      })
    ));
    let dirty = false;
    for (const [prj, pkgs] of projPkgMap.entries()) {
      project2Packages.set(pathToProjKey(prj), pkgs.map(pkgs => pkgs.name));
      dirty = true;
    }
    if (dirty)
      o.ft.project2Packages(project2Packages).dp(m);

    dirty = false;
    for (const [srcDir, pkgs] of srcPkgMap.entries()) {
      srcDir2Packages.set(pathToProjKey(srcDir), pkgs.map(pkgs => pkgs.name));
      dirty = true;
    }
    if (dirty)
      o.ft.srcDir2Packages(srcDir2Packages).dp(m);

    o.ft.inited(true).dp(m);
    // o.ft.onScanned().dp(m);
    const srcPackages = new Map<string, PackageInfo>();
    for (const pkInfo of pkgList) {
      srcPackages.set(pkInfo.name, pkInfo);
    }
    o.ft.srcPackages(srcPackages).dp(m);
  })
));

r('syncWorkspace, srcPackages -> currWorkspace', i.pt.syncWorkspace.pipe(
  rx.concatMap(([m, wsKey]) => rx.combineLatest([
    outputTable.l.srcPackages,
    outputTable.l.workspaces
  ]).pipe(
    rx.take(1),
    rx.tap(([[, srcPackages], [, workspaces]]) => {
      const wsDir = Path.resolve(rootDir, wsKey);
      o.ft.currWorkspace(wsKey).dp(m);
      const symlinkDir = Path.resolve(wsDir, symlinkDirName || 'node_modules');
      if (!fsext.existsSync(symlinkDir))
        fsext.mkdirpSync(symlinkDir);
      const pkgjsonFile = Path.resolve(wsDir, 'package.json');
      const lockFile = Path.resolve(wsDir, 'plink2.install.lock');
      let pkjsonStr: string;
      if (fs.existsSync(lockFile)) {
        log.warn('Plink sync process was interrupted last time, recover content of ' + pkgjsonFile);
        pkjsonStr = fs.readFileSync(lockFile, 'utf8');
        fs.unlinkSync(lockFile);
      } else {
        pkjsonStr = fs.readFileSync(pkgjsonFile, 'utf8');
      }
      // eslint-disable-next-line @typescript-eslint/no-unsafe-assignment
      const pkjson = JSON.parse(pkjsonStr) as PackageJsonInterf;

      const [linkedDependencies, toInstallDeps] = createDependencies(pkjson.dependencies, srcPackages);
      const [linkedDevDependencies, toInstallDevDeps] = createDependencies(pkjson.devDependencies, srcPackages);
      const installJson = {
        ...pkjson,
        dependencies: toInstallDeps,
        devDependencies: toInstallDevDeps
      };
      let workspaceState = workspaces.get(wsKey);
      if (workspaceState == null) {
        workspaceState = {
          id: wsKey
        } as WorkspaceState;
        workspaces.set(wsKey, workspaceState);
      }
      workspaceState.installJson = installJson;
      workspaceState.installJsonStr = JSON.stringify(installJson, null, '  ');
      workspaceState.linkedDependencies = linkedDependencies;
      workspaceState.linkedDevDependencies = linkedDevDependencies;
      // checkAllWorkspaces();
    })
  ))
));

o.ft.inited(false).dp();
o.ft.workspaces(new Map()).dp();
o.ft.project2Packages(new Map()).dp();
o.ft.srcDir2Packages(new Map()).dp();
// o.ft.srcPackages(new Map()).dp();
o.ft.gitIgnores({}).dp();
o.ft.workspaceUpdateChecksum(0).dp();
o.ft.packagesUpdateChecksum(0).dp();
o.ft.npmInstallOpt({isForce: false}).dp();
o.ft.currWorkspace(null).dp();
o.ft.linkedDrcp().dp();
o.ft.linkedDrcpProject().dp();
o.ft.installedDrcp().dp();
o.ft.isInChina().dp();
o.ft.lastCreatedWorkspace().dp();

function createDependencies(dependencies: Record<string, string> | undefined, srcPackages: Map<string, PackageInfo>) {
  const sourceDeps = [] as [string, string][];
  const toInstallDeps = {} as Record<string, string>;
  for (const pair of Object.entries<string>(dependencies || {})) {
    const [name, ver] = pair;
    const pkgInfo = srcPackages.get(name);
    if (pkgInfo) {
      sourceDeps.push(pair);
      toInstallDeps[name] = pkgInfo.realPath;
    } else {
      toInstallDeps[name] = ver;
    }
  }

  return [sourceDeps, toInstallDeps] as const;
}
